import { sql } from "drizzle-orm";
import { check, integer, jsonb, pgTable, text } from "drizzle-orm/pg-core";

import { instant, timestamps, version } from "../columns";

/**
 * Platform-wide tables (04-veri §10, adapted by plan K-07 and K-15). Auth tables are generated by
 * the Better Auth CLI into ./auth.ts. The tenant root is ./venues.ts; tables that belong to one
 * venue (venue_domains, venue_settings, menus …, audit_logs, demo_outbox) live in
 * src/server/db/tenant/tables/ with row level security (ADR-0004).
 *
 * Not used in this project: site_settings (→ platform_settings + venue_settings), leads and
 * consent_records (no visitor form, no visitor personal data — K-15).
 */

/** Single-row, versioned platform configuration (name, introduction texts, SEO). */
export const platformSettings = pgTable(
  "platform_settings",
  {
    id: text().primaryKey().default("singleton"),
    name: text().notNull(),
    tagline: text().notNull(),
    description: text().notNull(),
    contact: jsonb().$type<{ phone: string; email: string }>().notNull(),
    legalName: text().notNull(),
    seo: jsonb().$type<{ titleTemplate: string; defaultDescription: string }>().notNull(),
    ...version,
    ...timestamps,
  },
  (table) => [check("ck_platform_settings_singleton", sql`${table.id} = 'singleton'`)],
);

/** Fixed-window counters for action rate limits (11-guvenlik §9). Auth has its own limiter. */
export const actionRateLimits = pgTable("action_rate_limits", {
  key: text().primaryKey(),
  count: integer().notNull().default(0),
  expiresAt: instant().notNull(),
});
